mkuse!{use std :: ops :: ControlFlow ;}
mkuse!{use rustc_data_structures :: fx :: FxIndexSet ;}
mkuse!{use rustc_type_ir :: TypeFoldable ;}
mkuse!{use crate :: ty :: { self , Binder , Ty , TyCtxt , TypeFlags , TypeSuperVisitable , TypeVisitable , TypeVisitor , } ;}
mkitem!{mkimpl!{impl < 'tcx > TyCtxt < 'tcx > { # [doc = " Invoke `callback` on every region appearing free in `value`."] pub fn for_each_free_region (self , value : & impl TypeVisitable < TyCtxt < 'tcx > > , mut callback : impl FnMut (ty :: Region < 'tcx >) ,) { self . any_free_region_meets (value , | r | { callback (r) ; false }) ; } # [doc = " Returns `true` if `callback` returns true for every region appearing free in `value`."] pub fn all_free_regions_meet (self , value : & impl TypeVisitable < TyCtxt < 'tcx > > , mut callback : impl FnMut (ty :: Region < 'tcx >) -> bool ,) -> bool { ! self . any_free_region_meets (value , | r | ! callback (r)) } # [doc = " Returns `true` if `callback` returns true for some region appearing free in `value`."] pub fn any_free_region_meets (self , value : & impl TypeVisitable < TyCtxt < 'tcx > > , callback : impl FnMut (ty :: Region < 'tcx >) -> bool ,) -> bool { struct RegionVisitor < F > { # [doc = " The index of a binder *just outside* the things we have"] # [doc = " traversed. If we encounter a bound region bound by this"] # [doc = " binder or one outer to it, it appears free. Example:"] # [doc = ""] # [doc = " ```ignore (illustrative)"] # [doc = "       for<'a> fn(for<'b> fn(), T)"] # [doc = " // ^          ^          ^     ^"] # [doc = " // |          |          |     | here, would be shifted in 1"] # [doc = " // |          |          | here, would be shifted in 2"] # [doc = " // |          | here, would be `INNERMOST` shifted in by 1"] # [doc = " // | here, initially, binder would be `INNERMOST`"] # [doc = " ```"] # [doc = ""] # [doc = " You see that, initially, *any* bound value is free,"] # [doc = " because we've not traversed any binders. As we pass"] # [doc = " through a binder, we shift the `outer_index` by 1 to"] # [doc = " account for the new binder that encloses us."] outer_index : ty :: DebruijnIndex , callback : F , } impl < 'tcx , F > TypeVisitor < TyCtxt < 'tcx > > for RegionVisitor < F > where F : FnMut (ty :: Region < 'tcx >) -> bool , { type Result = ControlFlow < () > ; fn visit_binder < T : TypeVisitable < TyCtxt < 'tcx > > > (& mut self , t : & Binder < 'tcx , T > ,) -> Self :: Result { self . outer_index . shift_in (1) ; let result = t . super_visit_with (self) ; self . outer_index . shift_out (1) ; result } fn visit_region (& mut self , r : ty :: Region < 'tcx >) -> Self :: Result { match r . kind () { ty :: ReBound (debruijn , _) if debruijn < self . outer_index => { ControlFlow :: Continue (()) } _ => { if (self . callback) (r) { ControlFlow :: Break (()) } else { ControlFlow :: Continue (()) } } } } fn visit_ty (& mut self , ty : Ty < 'tcx >) -> Self :: Result { if ty . flags () . intersects (TypeFlags :: HAS_FREE_REGIONS) { ty . super_visit_with (self) } else { ControlFlow :: Continue (()) } } } value . visit_with (& mut RegionVisitor { outer_index : ty :: INNERMOST , callback }) . is_break () } # [doc = " Returns a set of all late-bound regions that are constrained"] # [doc = " by `value`, meaning that if we instantiate those LBR with"] # [doc = " variables and equate `value` with something else, those"] # [doc = " variables will also be equated."] pub fn collect_constrained_late_bound_regions < T > (self , value : Binder < 'tcx , T > ,) -> FxIndexSet < ty :: BoundRegionKind > where T : TypeFoldable < TyCtxt < 'tcx > > , { self . collect_late_bound_regions (value , true) } # [doc = " Returns a set of all late-bound regions that appear in `value` anywhere."] pub fn collect_referenced_late_bound_regions < T > (self , value : Binder < 'tcx , T > ,) -> FxIndexSet < ty :: BoundRegionKind > where T : TypeFoldable < TyCtxt < 'tcx > > , { self . collect_late_bound_regions (value , false) } fn collect_late_bound_regions < T > (self , value : Binder < 'tcx , T > , just_constrained : bool ,) -> FxIndexSet < ty :: BoundRegionKind > where T : TypeFoldable < TyCtxt < 'tcx > > , { let mut collector = LateBoundRegionsCollector :: new (just_constrained) ; let value = value . skip_binder () ; let value = if just_constrained { self . expand_free_alias_tys (value) } else { value } ; value . visit_with (& mut collector) ; collector . regions } }}}
mkitem!{mkstruct!{# [doc = " Collects all the late-bound regions at the innermost binding level"] # [doc = " into a hash set."] struct LateBoundRegionsCollector { current_index : ty :: DebruijnIndex , regions : FxIndexSet < ty :: BoundRegionKind > , # [doc = " `true` if we only want regions that are known to be"] # [doc = " \"constrained\" when you equate this type with another type. In"] # [doc = " particular, if you have e.g., `&'a u32` and `&'b u32`, equating"] # [doc = " them constraints `'a == 'b`. But if you have `<&'a u32 as"] # [doc = " Trait>::Foo` and `<&'b u32 as Trait>::Foo`, normalizing those"] # [doc = " types may mean that `'a` and `'b` don't appear in the results,"] # [doc = " so they are not considered *constrained*."] just_constrained : bool , }}}
mkitem!{mkimpl!{impl LateBoundRegionsCollector { fn new (just_constrained : bool) -> Self { Self { current_index : ty :: INNERMOST , regions : Default :: default () , just_constrained } } }}}
mkitem!{mkimpl!{impl < 'tcx > TypeVisitor < TyCtxt < 'tcx > > for LateBoundRegionsCollector { fn visit_binder < T : TypeVisitable < TyCtxt < 'tcx > > > (& mut self , t : & Binder < 'tcx , T >) { self . current_index . shift_in (1) ; t . super_visit_with (self) ; self . current_index . shift_out (1) ; } fn visit_ty (& mut self , t : Ty < 'tcx >) { if self . just_constrained { match t . kind () { ty :: Alias (ty :: Projection | ty :: Inherent | ty :: Opaque , _) => { return ; } ty :: Alias (ty :: Free , _) => bug ! ("unexpected free alias type") , _ => { } } } t . super_visit_with (self) } fn visit_const (& mut self , c : ty :: Const < 'tcx >) { if self . just_constrained { if let ty :: ConstKind :: Unevaluated (..) = c . kind () { return ; } } c . super_visit_with (self) } fn visit_region (& mut self , r : ty :: Region < 'tcx >) { if let ty :: ReBound (debruijn , br) = r . kind () { if debruijn == self . current_index { self . regions . insert (br . kind) ; } } } }}}